insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('prms', 'intermediate', 'module', 'm01-project-maturity-sub-classes', 1, 'A discovered project meets every commerciality criterion with established technology. Its investment has been sanctioned and its wells are still being built. Which Reserves sub-class does the engine derive?', '["justified-for-development", "approved-for-development", "on-production", "development-pending"]'::jsonb, 1, 'The engine derives the sub-class from the two stated facts: decision taken and no production gives approved-for-development (PRMS 2.1.3.5.5, Table 1), the sub-class of Ekene infill wells (EKN-2). Justified-for-development is the step before, with no investment decision yet. On-production needs the project on production. Development-pending is a Contingent Resources sub-class and cannot apply to a commercial project.'),
  ('prms', 'intermediate', 'module', 'm01-project-maturity-sub-classes', 2, 'The golden input class-justified states a commercial project with the final investment decision not taken and production not started. What sub-class does the engine return?', '["approved-for-development, since every commerciality criterion is met here", "development-pending, as the decision is still to come", "No sub-class until the investment decision is taken", "justified-for-development: no final investment decision yet"]'::jsonb, 3, 'With neither fact true the engine returns justified-for-development and prints the decision "justified-for-development: no final investment decision yet". Approved-for-development needs the decision taken. Development-pending belongs to Contingent Resources, and this project is commercial. The engine always returns a sub-class for a Reserves project; the missing decision is what sets this one.'),
  ('prms', 'intermediate', 'module', 'm01-project-maturity-sub-classes', 3, 'For a project it finds commercial, which two stated facts does the engine read to derive the Reserves sub-class?', '["Whether the final investment decision is taken and whether the project is on production", "The reserves status and the stated economic status of the project", "The years to the start of development and whether a longer wait is justified", "Its chance of development and whether the firm intention to proceed is stated"]'::jsonb, 0, 'The Reserves sub-class is derived from the project status: finalInvestmentDecision and onProduction, each a stated true or false (PRMS 2.1.3.5, Table 1). The reserves status is stated for Reserves and checked against the project status; it sets no sub-class. The start and its justification set the time-frame criterion, which decides the class. A Reserves project carries no chance at all, and the firm intention is a commerciality fact.'),
  ('prms', 'intermediate', 'module', 'm01-project-maturity-sub-classes', 4, 'Ekene Main waterflood (EKN-1) is stated as on production. In a copy of it the final investment decision is set to false. What does the engine return?', '["The sub-class justified-for-development, read from the missing decision", "On-production, as production outranks it", "A refusal naming projectStatus.finalInvestmentDecision", "A refusal naming subClass, which must change to approved-for-development"]'::jsonb, 2, 'A producing project has passed its investment decision, so the engine refuses the contradiction in the facts and names the fact to fix: "projectStatus.finalInvestmentDecision must be true for a project on production (a producing project has passed its investment decision); got false". It derives no sub-class from facts that disagree, so neither justified-for-development nor on-production comes back, and the refusal names the decision field, since the sub-class check never gets that far.'),
  ('prms', 'intermediate', 'module', 'm01-project-maturity-sub-classes', 5, 'Ekene infill wells (EKN-2) has its investment decision taken and is not on production. In a copy, the reserves status is changed to developed-producing. What happens?', '["The call returns developed-producing as stated, since the reserves status is a stated fact the engine records", "The sub-class moves up to on-production to match the stated reserves status", "The call is refused on reservesStatus, which must be developed-non-producing or undeveloped", "The call is refused on subClass, which must then read on-production"]'::jsonb, 2, 'Developed producing reserves come from completion intervals open and producing (PRMS 2.1.3.6, Table 2), so the engine refuses on reservesStatus and names the two statuses a project not on production may carry. The status is stated and it is also checked. The engine never moves a sub-class to fit a status; the sub-class follows the project status, and here the project is not on production.'),
  ('prms', 'intermediate', 'module', 'm01-project-maturity-sub-classes', 6, 'How does the engine set the sub-class of a Contingent Resources project?', '["It takes the stated one and checks only that it is one of the four", "It derives it from the list of blockers that the commerciality test names for the project", "It reads it from the stated economic status of the project", "It derives it from the stated chance of development, Pd"]'::jsonb, 0, 'The engine cannot see why a development is waiting, so the Contingent sub-class is stated and checked against the four of PRMS 2.1.3.5.6 and Table 1: development-pending, development-on-hold, development-unclarified and development-not-viable. The blockers and the economic status are printed beside it, and the chance of development sets the chance of commerciality; none of them sets the sub-class.'),
  ('prms', 'intermediate', 'module', 'm01-project-maturity-sub-classes', 7, 'In a copy of Ekene East gas (EKN-3), the stated sub-class development-on-hold is changed to development-not-viable, and nothing else moves. What does the engine return?', '["A refusal: the not-viable sub-class needs a not-viable economic status", "Contingent Resources, with the sub-class reset to development-on-hold", "Discovered Unrecoverable, since no project is planned for it any more", "Contingent Resources, sub-class development-not-viable (stated)"]'::jsonb, 3, 'The engine accepts any of the four Contingent sub-classes on any Contingent project, so it returns the class with development-not-viable as stated and the same six blockers. Nothing ties the sub-class to the economic status, and the engine never rewrites a stated input. Discovered Unrecoverable needs no recovery project at all, and EKN-3 states one with established technology. Whether the sub-class fits the blockers is a judgement left to the person who signs the report.'),
  ('prms', 'intermediate', 'module', 'm01-project-maturity-sub-classes', 8, 'The appraisal project EKN-4, already discovered, carries a stated Pd of 65.000000 percent. Which Pc appears in its decisions?', '["No figure for a discovered project", "65.000000 percent, from Pc = Pd", "50.000000 percent, as Ekene East gas", "A refusal until a Pg is stated first"]'::jsonb, 1, 'A discovered project has already met its geology, so its chance of commerciality is the chance of development alone (PRMS 2.1.3.3). The engine''s decision line is "Pc = Pd = 65%". Only Reserves carry no chance. 50.000000 percent is EKN-3''s Pd. A chance of geologic discovery on a discovered project is refused, so asking for one would be the error.'),
  ('prms', 'intermediate', 'module', 'm01-project-maturity-sub-classes', 9, 'A copy of a Contingent project states chances.geologicDiscoveryPct as 50 beside its chance of development. Which field does the engine refuse?', '["chances.geologicDiscoveryPct, which applies to Prospective Resources only", "chances, since a Contingent project may state no chance of any kind", "chances.developmentPct, which must then fall to the product of both", "subClass, which must change to prospect once Pg is stated"]'::jsonb, 0, 'The engine''s message reads "chances.geologicDiscoveryPct must be left out for a discovered accumulation (the chance of geologic discovery applies to Prospective Resources, PRMS 2.1.3.2); got 50". A Contingent project must state its chance of development, so the chances object is required. The engine computes Pc = Pd for it and multiplies nothing. The discovery status sets the class, and a stated chance never turns a discovered project into a prospect.'),
  ('prms', 'intermediate', 'module', 'm01-project-maturity-sub-classes', 10, 'Ekene Shallow lead (EKN-7) states a chance of geologic discovery of 15.000000 percent and a chance of development of 70.000000 percent. What chance of commerciality does the engine return?', '["15.000000 percent", "70.000000 percent", "10.500000 percent", "20.000000 percent"]'::jsonb, 2, 'For an undiscovered project the chance of commerciality is the product Pc = Pg x Pd (PRMS 2.1.3.3), and the engine returns 10.500000 percent for EKN-7. Pg alone ignores the chance of development if found; Pd alone is the discovered-project rule. 20.000000 percent is EKN-6, whose Pg of 25.000000 and Pd of 80.000000 give a different product.'),
  ('prms', 'intermediate', 'module', 'm01-project-maturity-sub-classes', 11, 'The golden input class-pg-zero states a prospect with a chance of geologic discovery of 0 and a chance of development of 50.000000 percent. What does the engine return?', '["Undiscovered Unrecoverable, since nothing can ever be found at that chance of discovery", "A refusal: a chance of geologic discovery must be above 0", "Prospective Resources with a Pc of 50.000000, from Pd", "Prospective Resources, sub-class prospect, with a Pc of 0.000000"]'::jsonb, 3, 'The engine classifies the facts it is given: an undiscovered accumulation with a recovery project is Prospective Resources, and the product 0 x 50 gives a Pc of 0.000000. Unrecoverable needs no recovery project, and this one states established technology. A chance of 0 lies inside the accepted range from 0 to 100, so there is nothing to refuse. Pd alone is the rule for a discovered project.'),
  ('prms', 'intermediate', 'module', 'm01-project-maturity-sub-classes', 12, 'A copy of an undiscovered project states the sub-class development-pending. What does the engine return?', '["Contingent Resources, since the stated sub-class belongs to that class", "The refusal: subClass must be one of \"prospect\", \"lead\", \"play\"; got \"development-pending\"", "Prospective Resources with the stated sub-class printed beside it", "A refusal on discovery, which must change to discovered first"]'::jsonb, 1, 'Prospective Resources carry three stated sub-classes (PRMS 2.1.3.5.9, Table 1), and the engine checks the stated one is among them. The discovery status sets the class, and a stated sub-class never moves a project across the class line. The engine does not print a sub-class it has refused, and the discovery field is valid as stated, so the refusal names subClass.'),
  ('prms', 'intermediate', 'module', 'm01-project-maturity-sub-classes', 13, 'On a commercial project with finalInvestmentDecision true and onProduction false, the box states subClass as development-pending. What does the refusal ask for?', '["One of the four Contingent Resources sub-classes, listed in full", "A project status with both facts false, to fit development-pending", "A chance of development for the pending project", "The sub-class approved-for-development, which the facts give"]'::jsonb, 3, 'The class is decided first, from the criteria, and this project is Reserves. The message reads "subClass must be "approved-for-development" for this project (final investment decision taken; production yet to start: PRMS 2.1.3.5.5, Table 1); got "development-pending"". The list of four Contingent sub-classes appears only when the facts make a project Contingent. The engine asks the stated sub-class to follow the facts, and a Reserves project carries no chance.'),
  ('prms', 'intermediate', 'module', 'm01-project-maturity-sub-classes', 14, 'A project that fails six commerciality criteria states the sub-class approved-for-development. What does the engine do?', '["Refuses subClass, listing the four Contingent sub-classes and the six blockers", "Classifies it as Reserves, since approved-for-development is a Reserves sub-class", "Refuses projectStatus, since an approved project must state its decision", "Returns Contingent Resources and prints the stated sub-class beside the blockers"]'::jsonb, 0, 'A stated sub-class does not make a project commercial; the criteria do. The engine decides Contingent Resources first, then refuses: "subClass must be one of "development-pending", "development-on-hold", "development-unclarified", "development-not-viable" for Contingent Resources (not commercial: financialAppropriations, timeFrame, economicStatus, market, facilities, firmIntention)". A project status is read for Reserves alone, and the engine never returns a result that carries a sub-class from the wrong class.'),
  ('prms', 'intermediate', 'module', 'm01-project-maturity-sub-classes', 15, 'A classification box carries the top-level key maturity beside the usual facts. What comes back?', '["The class and sub-class, with the unknown key dropped silently", "A sub-class read from the maturity key in place of subClass", "A refusal: maturity is not an accepted key, with the accepted top-level keys listed", "A refusal naming subClass, which the maturity key hides"]'::jsonb, 2, 'Every function checks its accepted keys before it reads a fact, and it drops nothing silently. The message reads "maturity is not an accepted key; the accepted keys at the top level are name, discovery, recoveryProject, subClass, commerciality, economicStatus, projectStatus, reservesStatus, chances, nigeria". The engine reads no key it does not know, so a maturity key is never read as a sub-class, and the key check runs before the sub-class check.'),
  ('prms', 'intermediate', 'module', 'm02-the-seven-commerciality-criteria', 1, 'Ekene North appraisal (EKN-4) states economic status viable, a start within 3 years, a market and facilities. Which criteria does the engine name as holding it back?', '["firmIntention alone, since its economics are already viable", "financialAppropriations, timeFrame, economicStatus, market, facilities, firmIntention", "developmentPlan, financialAppropriations, approvals, firmIntention", "None: a viable economic status settles commerciality by itself"]'::jsonb, 2, 'The engine returns Contingent Resources for EKN-4 with the blockers developmentPlan, financialAppropriations, approvals and firmIntention. Positive economics is one criterion of seven plus the commitment, and every one must be met, so viable economics settles nothing alone and the commitment is one blocker among four. The six-item list belongs to Ekene East gas (EKN-3), which lacks a market and facilities.'),
  ('prms', 'intermediate', 'module', 'm02-the-seven-commerciality-criteria', 2, 'Of the seven criteria and the commitment, six are stated as true or false. Which two does the engine read from other inputs?', '["The time-frame, from a stated start and justification, and positive economics, from the economic status", "The market and the facilities, which it reads from the stated forecast and prices", "The plan and the money, which it reads from the capital rows of the cost table", "Approvals and the commitment, both read from the Nigerian declaration"]'::jsonb, 0, 'The time-frame is met from commerciality.timeFrame (startWithinYears and longerJustified) against the five-year benchmark, and positive economics is met only when the stated economic status is viable. A market, facilities, the plan, the money, approvals and the firm intention are each a stated true or false; the classification reads no forecast or cost table, and the Nigerian declaration is a note that moves no class.'),
  ('prms', 'intermediate', 'module', 'm02-the-seven-commerciality-criteria', 3, 'One golden input differs from a Reserves project only in its start date: 6 years out, with no justification stated for waiting beyond the benchmark. What class comes back?', '["Reserves, since five years is only a recommended benchmark of the standard", "A refusal on startWithinYears, which must lie at or below 5", "Contingent Resources, with timeFrame and firmIntention as blockers", "Contingent Resources, with timeFrame as its one blocker"]'::jsonb, 3, 'The reason reads "time-frame: development starts within 6 years against the 5-year benchmark, a longer time-frame not stated as justified: not met (PRMS 2.1.2.3)", so the class is Contingent Resources and timeFrame is the only blocker. The benchmark is a recommendation, and the engine applies it unless a longer time-frame is stated as justified. A start of 6 is a valid input; only a negative one is refused. The commitment is met on this input.'),
  ('prms', 'intermediate', 'module', 'm02-the-seven-commerciality-criteria', 4, 'When the start is 8 years away and the box says the longer wait is justified, which line is printed for criterion (3)?', '["time-frame: development starts within 8 years against the 5-year benchmark: not met (PRMS 2.1.2.3)", "time-frame: development starts within 8 years against the 5-year benchmark, a longer time-frame stated as justified: met (PRMS 2.1.2.3)", "A refusal: startWithinYears must be at most 5 when a longer time-frame is stated", "time-frame: not tested, since the justification replaces the benchmark"]'::jsonb, 1, 'A start beyond five years meets the criterion when a longer time-frame is stated as justified, and the engine prints the justification in its line, so the class is Reserves. The not-met line would need the justification false. No start of 0 or more is refused on its size, and the engine tests the time-frame on every discovered project with a recovery project, printing the justification it was given.'),
  ('prms', 'intermediate', 'module', 'm02-the-seven-commerciality-criteria', 5, 'An otherwise commercial project is due to begin development in exactly 5 years, with nothing stated about a longer wait. What does the engine return for the time-frame criterion?', '["Not met, with one blocker, timeFrame", "Met, with the class Reserves", "A refusal until the edge is justified", "Met once a longer wait is justified"]'::jsonb, 1, 'The engine prints "time-frame: development starts within 5 years against the 5-year benchmark: met (PRMS 2.1.2.3)" and returns Reserves. Reading five years exactly as met is the engine''s stated reading of the edge; the alternative it names reads it as not met, and no graded figure rests on the edge. A start on the benchmark is a valid input, and no justification is needed within five years.'),
  ('prms', 'intermediate', 'module', 'm02-the-seven-commerciality-criteria', 6, 'The golden input class-economics-undetermined meets every other criterion and states economic status undetermined. What does the engine return?', '["Reserves, since undetermined economics are not negative economics", "A refusal: the economic status must be viable or not-viable", "Contingent Resources, sub-class development-not-viable by derivation", "Contingent Resources, blocked by economicStatus"]'::jsonb, 3, 'Only viable meets criterion (4), positive economics (PRMS 2.1.2.1(4), 2.1.3.7.1), so an undetermined status leaves the project Contingent with the single blocker economicStatus. Undetermined is one of the three accepted words, so nothing is refused. The engine derives no Contingent sub-class; it checks the stated one.'),
  ('prms', 'intermediate', 'module', 'm02-the-seven-commerciality-criteria', 7, 'Someone types "positive" as the stated economic status of a discovered project. How does the engine respond?', '["economicStatus must be one of \"viable\", \"not-viable\", \"undetermined\"; got \"positive\"", "The class Reserves, with positive read as the same word as viable on every criterion line", "Contingent Resources, with economicStatus blocking as a word the engine does not know", "commerciality.economics must be true or false (stated; no default); got \"positive\""]'::jsonb, 0, 'The engine accepts exactly three words for the economic status and refuses anything else by name, printing the value it was given. It maps no synonym onto viable, and a refusal returns no class. Positive economics is read from economicStatus, a top-level input, and commerciality carries no economics key.'),
  ('prms', 'intermediate', 'module', 'm02-the-seven-commerciality-criteria', 8, 'Starting from the on-production Ekene project, a user deletes the market criterion from the box. Which message comes back?', '["Reserves, the missing market read as met because the project is on production", "Contingent Resources, blocked by market, which it reads as not met", "commerciality.market must be true or false (stated; no default); got nothing", "commerciality must be an object with seven keys; got six"]'::jsonb, 2, 'Every criterion is a stated fact with no default, so a missing one is refused by name and the message says it got nothing. The engine never fills a criterion from another fact, in either direction, so it returns neither Reserves nor a Contingent class with market blocked. The refusal names the missing key itself, commerciality.market.'),
  ('prms', 'intermediate', 'module', 'm02-the-seven-commerciality-criteria', 9, 'For the approvals criterion a user enters the string "yes". Which message comes back?', '["A refusal on commerciality.approvals that prints the value \"yes\" as it was given", "Reserves, the word yes read as true for approvals", "approvals is not an accepted key; the accepted keys are listed", "Contingent Resources, blocked by approvals until a boolean is stated"]'::jsonb, 0, 'A criterion is true or false and nothing else; a string is refused on the field that carries it, with the value printed as given. The engine reads no word as a boolean, so neither class comes back. The key approvals is an accepted key of commerciality, so the unknown-key message does not apply.'),
  ('prms', 'intermediate', 'module', 'm02-the-seven-commerciality-criteria', 10, 'A box spells one criterion as commerciality.markets. What comes back?', '["The class, with the misspelt key dropped silently and market left unread", "A refusal naming commerciality.market as missing", "The class, with markets read as the market criterion", "It is refused on the misspelt key, and the message lists the seven keys commerciality accepts"]'::jsonb, 3, 'The engine checks accepted keys before it reads any input, so the misspelling is refused first: "commerciality.markets is not an accepted key; the accepted keys of commerciality are developmentPlan, financialAppropriations, timeFrame, market, facilities, approvals, firmIntention". It drops no key silently and reads no near-match for a key it knows. The missing market would be refused only after the spelling is fixed.'),
  ('prms', 'intermediate', 'module', 'm02-the-seven-commerciality-criteria', 11, 'The golden input class-no-firm-intention meets every criterion and states the commitment as not met. Which line does the engine print for it?', '["(7) legal, contractual, environmental, regulatory and government approvals in place or forthcoming: not met", "commitment: not tested, since the seven criteria are met", "commitment: the entity''s firm intention to proceed with development: not met (PRMS 2.1.2.1, 2.1.2.3)", "Reserves: every commerciality criterion is met with established technology"]'::jsonb, 2, 'The engine carries the commitment as a stated fact beside the seven criteria and prints it with its section; here it is not met, so the class is Contingent Resources with the single blocker firmIntention. Approvals are met on this input. The commitment is tested on every discovered project with a recovery project, whatever the seven show, and the Reserves decision line needs the commitment met.'),
  ('prms', 'intermediate', 'module', 'm02-the-seven-commerciality-criteria', 12, 'A discovered project passes all seven criteria and the commitment, yet its recovery method is still being proven in the field. Which result does the engine give?', '["Reserves, since every one of the seven criteria and the commitment is met", "Contingent Resources, with the blocker \"technology under development\"", "Discovered Unrecoverable, because no established technology applies", "A refusal on recoveryProject, which must state established-technology here"]'::jsonb, 1, 'Reserves need every criterion met with established technology, so technology under development keeps the project in Contingent Resources and the engine names it as the blocker. Unrecoverable needs no recovery project at all, and a project with technology under development has one. Technology under development is one of the accepted recovery projects, so nothing is refused.'),
  ('prms', 'intermediate', 'module', 'm02-the-seven-commerciality-criteria', 13, 'The start of development is entered as -1 years in commerciality.timeFrame. What is the result?', '["time-frame: development starts within -1 years against the 5-year benchmark: met", "Reserves, since a start already past is well inside the benchmark", "commerciality.timeFrame must be an object { startWithinYears, longerJustified }; got -1", "commerciality.timeFrame.startWithinYears must be a finite number at or above 0; got -1"]'::jsonb, 3, 'A start in the past is no time-frame, so the engine refuses the field that carries it and prints the value. It tests no benchmark on a refused input, so no time-frame line and no class come back. The timeFrame object itself is present and accepted; the refusal names the one key inside it that fails.'),
  ('prms', 'intermediate', 'module', 'm02-the-seven-commerciality-criteria', 14, 'A project meets every commerciality criterion and states the Nigerian declaration as a significant gas discovery. What does the engine return?', '["A refusal on nigeria.declaration, which must be \"commercial-discovery\" for such a project", "Contingent Resources, since a significant discovery cannot yet be declared commercial", "Reserves, with the stated declaration printed beside the class as a note that moves no class at all", "Reserves, with a note printed that the retention period of the declared area runs at most 10 years"]'::jsonb, 0, 'The engine keeps the note consistent with the class: "nigeria.declaration must be "commercial-discovery" for a project that meets every commerciality criterion: a significant discovery cannot be declared commercial (PIA 2021 s.318) and a discovery of no interest is not being developed (s.78(8)(c)); got "significant-gas-discovery"". The declaration never changes the class, so the project does not fall to Contingent Resources, and a contradicting note is refused before any Reserves result is printed.'),
  ('prms', 'intermediate', 'module', 'm02-the-seven-commerciality-criteria', 15, 'In a copy of EKN-4, developmentPlan, financialAppropriations and approvals are set to true, and nothing else moves. What does the engine return?', '["Reserves, since economics, market, facilities and time-frame were already met", "firmIntention alone still blocks it, so it stays Contingent Resources", "Contingent Resources, with approvals and firmIntention still blocking", "Reserves, sub-class justified-for-development"]'::jsonb, 1, 'Setting the three criteria true leaves the stated commitment false, and the commitment is part of the commerciality test (PRMS 2.1.2.1, 2.1.2.3), so the project stays Contingent with firmIntention alone. Approvals are met in this copy. A Reserves class needs every criterion and the commitment, and the Reserves sub-class is only derived once the class is Reserves.'),
  ('prms', 'intermediate', 'module', 'm03-incremental-and-cumulative-categories', 1, 'The Ekene Main Reserves are stated cumulatively as 8.890000, 16.650000 and 24.990000 MMbbl. What Probable (P2) does the engine return?', '["16.650000 MMbbl", "8.340000 MMbbl", "8.890000 MMbbl", "7.760000 MMbbl"]'::jsonb, 3, 'The increment is a difference: Probable (P2) is the 2P less the 1P, and the engine returns 7.760000 MMbbl. 16.650000 is the cumulative 2P, which already includes the Proved (P1). 8.340000 is the Possible (P3), the 3P less the 2P. 8.890000 is the Proved (P1), which equals the 1P.'),
  ('prms', 'intermediate', 'module', 'm03-incremental-and-cumulative-categories', 2, 'On the same cumulative Ekene Main set, which figure carries the P90 label, and as which category?', '["24.990000 MMbbl, as the 3P, the 90th percentile of the range", "8.890000 MMbbl, as the 1P low estimate", "16.650000 MMbbl, the 2P", "7.760000 MMbbl, the Probable (P2)"]'::jsonb, 1, 'P90 is always the low estimate: the quantity met or exceeded with at least 90 percent probability when the method is probabilistic, so it sits on the 1P, 8.890000. The 3P carries the P10 label and the 2P the P50. An increment carries no probability label at all; the engine prints the labels beside the cumulative rows only.'),
  ('prms', 'intermediate', 'module', 'm03-incremental-and-cumulative-categories', 3, 'The golden input cat-faq33-incremental states Reserves as a first increment of 5, a second of 2 and a third of 3 MMbbl. Which 2P and 3P does the engine build?', '["10.000000 for the 3P, with the 2P at 7.000000", "3.000000 for the 3P, with the 2P at 2.000000: slices read as categories", "3.000000 for the 3P, with the 2P at 7.000000", "7.000000 for the 3P, with the 2P at 5.000000, one slice behind"]'::jsonb, 0, 'Cumulative categories are running sums of the increments: 1P = P1 = 5, 2P = P1 + P2 = 7 and 3P = P1 + P2 + P3 = 10, which the engine returns as 7.000000 and 10.000000. Reading a slice as a category ignores that each category includes the ones below it. Shifting the sums by one slice drops the Possible (P3) from the 3P.'),
  ('prms', 'intermediate', 'module', 'm03-incremental-and-cumulative-categories', 4, 'Ekene North''s Contingent Resources are stated incrementally as C1 3.000000, C2 1.500000 and C3 2.000000. What 2C does the engine return?', '["1.500000", "6.500000", "4.500000", "3.000000"]'::jsonb, 2, 'The 2C is C1 plus C2, 3.000000 plus 1.500000, and the engine returns 4.500000, the same figure it gives when the set is stated cumulatively (golden input cat-contingent-cumulative). 1.500000 is the slice C2 alone. 6.500000 is the 3C, which adds C3. 3.000000 is the 1C, the first slice.'),
  ('prms', 'intermediate', 'module', 'm03-incremental-and-cumulative-categories', 5, 'In the engine''s category output, which rows carry a probability label such as P90, P50 or P10?', '["The cumulative rows only; an increment carries none", "Every row, each increment taking the label of its own cumulative category", "Only the increments", "The 1P and the Proved (P1) alike"]'::jsonb, 0, 'The engine prints each cumulative row with its case, label, probability and value, and the increments with a label and a value only. An increment is a difference of two estimates, and there is no sense in which the Probable (P2) slice has a 50 percent chance. The 1P and the Proved (P1) share a value, and the P90 label still belongs to the cumulative 1P.'),
  ('prms', 'intermediate', 'module', 'm03-incremental-and-cumulative-categories', 6, 'A set stated with the cumulative method also carries a key second with the value 1. What does the engine return?', '["The categories from low, best and high, the extra key ignored", "The categories from the increments, which take precedence over the estimates", "second is not an accepted key; the accepted keys of estimates are listed", "estimates.second must be left out for the cumulative method (state low, best and high); got 1"]'::jsonb, 3, 'A set is one form or the other. With both a best estimate and a second increment there would be two answers for the 2P, and the engine picks neither; it refuses the key from the other form. It drops no key silently. Second is an accepted key of estimates for the incremental method, so the refusal is about mixing forms and is no unknown-key refusal.'),
  ('prms', 'intermediate', 'module', 'm03-incremental-and-cumulative-categories', 7, 'Under the method "incremental" a box also states a low estimate of 1. Which field does the refusal name?', '["estimates.first, which the low estimate would overwrite", "estimates.low, to be left out for the incremental method", "method, which must change to cumulative once a low is stated", "estimates, which must be ordered low <= best <= high"]'::jsonb, 1, 'The engine''s message reads "estimates.low must be left out for the incremental method (state first, second and third); got 1". It names the key from the wrong form, so the fix is to remove that key. The engine never changes a stated method to fit the keys, and ordering applies only to a cumulative set.'),
  ('prms', 'intermediate', 'module', 'm03-incremental-and-cumulative-categories', 8, 'A second increment is stated as -1. How does the engine treat it?', '["It accepts it and returns a 2P below the 1P", "It treats it as 0 and builds the categories from the rest", "It stops it at the input with a refusal on estimates.second", "It accepts it once the method is switched to cumulative"]'::jsonb, 2, 'A negative slice would put a smaller figure above a larger one, so the engine stops it at the input, with the message ending "got -1". It never rewrites an input to 0, and under the cumulative method the key second is refused outright. A zero increment, by contrast, is accepted.'),
  ('prms', 'intermediate', 'module', 'm03-incremental-and-cumulative-categories', 9, 'The golden input cat-zero-increment states Reserves incrementally as 0, 7 and 0 MMbbl. Which cumulative categories come back?', '["A refusal, since a Proved (P1) of 0 leaves no low estimate to label P90", "1P 0.000000, 2P 7.000000 and 3P 0.000000, each slice read as its own category", "1P 0.000000, 2P 7.000000 and 3P 7.000000", "1P, 2P and 3P all 7.000000"]'::jsonb, 2, 'A zero increment is accepted, and the running sums give 1P 0.000000, 2P 7.000000 and 3P 7.000000. A 1P of 0 says no quantity is confident enough to call proved, and a 3P equal to the 2P says the high case adds nothing. Only a negative increment is refused. The sums never drop back to 0 once a slice has been added, and a 1P of 7 would need a first increment of 7.'),
  ('prms', 'intermediate', 'module', 'm03-incremental-and-cumulative-categories', 10, 'A Prospective Resources set is stated with the incremental method. What does the engine return?', '["A refusal: method must be \"cumulative\" for Prospective Resources", "The categories 1U, 2U and 3U built from the stated increments", "The increments U1, U2 and U3 with cumulative sums beside them", "Contingent Resources increments C1, C2 and C3, relabelled"]'::jsonb, 0, 'PRMS 2.2.2.4 defines no incremental terms for Prospective Resources, and the engine refuses the incremental method for them, printing that section in its message. A Prospective set is stated cumulatively and returns 1U, 2U and 3U with no increments. The engine never relabels one class''s categories as another''s.'),
  ('prms', 'intermediate', 'module', 'm03-incremental-and-cumulative-categories', 11, 'The method control is set to not stated. Which message comes back?', '["method must be \"cumulative\" for Prospective Resources; got nothing", "The cumulative method is read from the low, best and high keys", "estimates must be ordered low <= best <= high; got nothing", "method must be one of \"cumulative\", \"incremental\"; got nothing"]'::jsonb, 3, 'The method has no default, so a missing method is refused by name and the message says it got nothing. The engine infers nothing from which keys are present. The Prospective refusal applies only when the incremental method is stated for that class, and the order check runs only on a stated cumulative set.'),
  ('prms', 'intermediate', 'module', 'm03-incremental-and-cumulative-categories', 12, 'On Ekene Main waterflood (EKN-1) the net-entitlement categories give a 2P oil of 9908615.920000 and a 1P oil of 5289968.880000 barrels. What Probable (P2) oil does the engine report?', '["9908615.920000 barrels", "4618647.040000 barrels", "5289968.880000 barrels", "4960152.645000 barrels"]'::jsonb, 1, 'Increments from three forecasts are exact differences of the three cut, entitled quantities, so the Probable (P2) oil is 9908615.920000 less 5289968.880000, which the engine returns as 4618647.040000. 9908615.920000 is the cumulative 2P. 5289968.880000 is the Proved (P1), equal to the 1P. 4960152.645000 is the Possible (P3) oil.'),
  ('prms', 'intermediate', 'module', 'm03-incremental-and-cumulative-categories', 13, 'On EKN-1 in BOE, the Possible (P3) is 5621506.350833 and the Probable (P2) is 5234466.685000. Why is the slice above the 2P the larger one?', '["The high case runs longer before its canonical economic limit", "The Possible (P3) carries the P10 label, which always sits highest", "The engine scales the Possible (P3) alone by the stated gas factor", "A mistake in the forecast, which the engine would refuse on order"]'::jsonb, 0, 'Each forecast is cut at its own canonical economic limit year: the best case in 2037 and the high case in 2040, so the high case keeps more years and the slice between the 2P and the 3P comes out larger. An increment carries no probability label. BOE converts the gas at 6.000000 Mscf per BOE for every row alike, and the cumulative categories are in order, so nothing is refused.'),
  ('prms', 'intermediate', 'module', 'm03-incremental-and-cumulative-categories', 14, 'Why can a set stated with the incremental method never be out of order?', '["The engine sorts the three increments before adding them", "Its keys are read as P90, P50 and P10", "Each running sum adds a slice that is zero or more", "An incremental set is checked for order only after the sums are built"]'::jsonb, 2, 'A negative slice is refused at the input, so every running sum is at least the one before and the 1P, 2P and 3P come out ordered. The engine sorts nothing, since sorting would change what was stated. The probability labels sit on the cumulative categories. No later order check is needed for this form, which is one reason to state increments when a set is built from separate pieces of work.'),
  ('prms', 'intermediate', 'module', 'm03-incremental-and-cumulative-categories', 15, 'The golden input cat-single-value states Reserves cumulatively as 2.000000, 2.000000 and 2.000000. Which increments come back?', '["A refusal: a range needs the low below the high", "Proved (P1), Probable (P2) and Possible (P3) each at 2.000000", "No increments: one value describes the whole range", "Proved (P1) 2.000000, with Probable (P2) and Possible (P3) at 0.000000"]'::jsonb, 3, 'Equal estimates are accepted: the order check allows low <= best <= high with equality. The engine returns the increments as differences, so the Proved (P1) is 2.000000 and the other two are 0.000000, and it adds that a single value may describe the expected result (PRMS 2.2.1.3). Three increments of 2 would put the 3P at three times the stated high, and the engine still prints increments for a single-value set.'),
  ('prms', 'intermediate', 'module', 'm04-the-economic-limit', 1, 'Ekene Main waterflood (EKN-1) states three technical forecasts from 2027 to 2041 and a licence expiring in 2040 with no renewal expected. In which years does the canonical trailing trim put the low, best and high economic limits?', '["2040 in all three cases", "2033, 2037 and 2040", "2041 in all three cases", "2040, 2037 and then 2033"]'::jsonb, 1, 'Each case is cut at its own canonical economic limit: the low in 2033 with 7 trailing years cut, the best in 2037 with 3, and the high in 2040 with 0. The licence cut removes 2041 from every case before the cash flow runs, and only the high case pays all the way to 2040. A smaller forecast stops paying sooner, so the low case reaches its limit first.'),
  ('prms', 'intermediate', 'module', 'm04-the-economic-limit', 2, 'After the licence cut and the canonical economic limit, how much oil does the EKN-1 best case keep on a gross basis?', '["18252916.000000 barrels", "9908615.920000 barrels", "16653136.000000 barrels", "11657195.200000 barrels"]'::jsonb, 2, 'The engine reports the economic oil, gross, of the best case as 16653136.000000: the technical 18252916.000000 less 308309.000000 beyond the licence and 1291471.000000 beyond the limit. 9908615.920000 is the same case on the net-entitlement basis, and 11657195.200000 on the working-interest basis; both apply a basis to the gross figure.'),
  ('prms', 'intermediate', 'module', 'm04-the-economic-limit', 3, 'Which trailing years does the canonical economic limit of cashflow.ts cut?', '["Trailing years whose revenue less royalty less opex is below 0, keeping capital years and years at exactly 0", "Every year whose net cash flow after tax and abandonment is below 0, wherever it falls in the forecast", "Every year after the one in which the cumulative net cash flow before tax peaks", "Trailing years whose production falls below the average rate of the forecast"]'::jsonb, 0, 'Working back from the last year, the trailing trim removes each year whose revenue less royalty less opex is negative; a year with capital is kept, and a year at exactly 0 is kept. It looks at trailing years only, and it ignores tax and abandonment. The cumulative peak is the PRMS 3.1.3.1 limit, which the engine checks against the trim and does not apply. No rule here uses an average rate.'),
  ('prms', 'intermediate', 'module', 'm04-the-economic-limit', 4, 'A golden input''s last year produces 19999 barrels at 50 a barrel against opex of 1000000. What economic limit and 2P oil does the engine return?', '["2029, the last year kept, and a 2P oil of 170000.000000", "2028, one trailing year cut, with the 2P oil still 170000.000000", "2029, the last year kept, and a 2P oil of 150000.000000", "2028, one trailing year cut, and a 2P oil of 150000.000000"]'::jsonb, 3, 'The last year''s revenue falls one barrel''s worth below its opex, so the trim cuts it: the limit is 2028 with 1 trailing year cut and the 2P oil is 150000.000000 (golden input econ-tail-one-below-cut). 170000.000000 belongs to the input with 20000 barrels, whose last year is kept. A cut year''s barrels leave the quantity with it, and a limit of 2029 keeps them.'),
  ('prms', 'intermediate', 'module', 'm04-the-economic-limit', 5, 'On the golden input econ-tail-exactly-zero-kept, 20000 barrels at 50 a barrel exactly meet opex of 1000000 in the last year. Why does that year stay inside the limit?', '["Any producing year is kept", "The last year of a forecast is never trimmed by the engine", "Its tax loss turns it positive", "The trim cuts only a year below 0"]'::jsonb, 3, 'The canonical trailing trim is strict on one side: a trailing year is cut when revenue less royalty less opex is below 0, and a year at exactly 0 is kept. So the limit is 2029 with 0 years cut and a 2P oil of 170000.000000. Production alone keeps nothing, as the 19999-barrel input shows; the last year is the first one the trim tests; and the trim reads no tax.'),
  ('prms', 'intermediate', 'module', 'm04-the-economic-limit', 6, 'What does the engine''s economic test ask of each case after the limit?', '["Whether its NPV at the stated discount rate is above 0 at 100 percent", "Whether its undiscounted net cash flow after tax and abandonment is above 0", "Whether its net cash flow at the working interest covers the capital alone", "Whether its net cash flow before tax and abandonment is at or above 0"]'::jsonb, 1, 'The basis reads "3.1.2.1 (undiscounted cumulative net cash flow above 0, ADR included), 3.1.2.8": undiscounted, after tax and abandonment, and strictly above 0. The discount rate sets the NPV and no verdict. The test runs at 100 percent, where a project either pays or does not. Leaving out tax and abandonment, or letting exactly 0 pass, changes what is tested.'),
  ('prms', 'intermediate', 'module', 'm04-the-economic-limit', 7, 'The golden input econ-exactly-zero-not-economic gives a best case undiscounted net cash flow of 0.000000. What status does the engine return?', '["Not commercial: the project stays in Contingent Resources, economically not viable", "Reserves, since a best case at exactly 0 does not lose money", "A refusal on forecasts.best, which must be economic on these costs", "Reserves with 1P set to 0, the FAQ 3.3 rule applied to the best case"]'::jsonb, 0, 'The engine calls a case economic only above 0, so a best case at exactly 0 fails and the status reads "not commercial: the best case fails the economic test (PRMS 2.1.2.2, 3.1.2.1); the project stays in Contingent Resources, economically not viable (PRMS 2.1.3.7.1)". Reading exactly 0 as not economic is the engine''s stated reading; the alternative it names reads it as economic, and no graded figure rests on the edge. A failing best case is a result with a reason, and the FAQ 3.3 rule concerns a failing low case.'),
  ('prms', 'intermediate', 'module', 'm04-the-economic-limit', 8, 'On the golden input econ-best-fails the best case returns an undiscounted net cash flow of -10000000.000000 and the high case passes. Which Reserves categories does the engine report?', '["A 3P of 9000000.000000 alone", "1P 0.000000 and 2P 7000000.000000", "No Reserves category at all", "A 2P of 7000000.000000"]'::jsonb, 2, 'The best case decides the class: when it fails, the engine reports no Reserves categories and says the project stays in Contingent Resources (PRMS 2.1.2.2, 3.1.2.1). A passing high case gives no 3P on its own. 1P 0.000000 with 2P 7000000.000000 is the FAQ 3.3 result, where the best case passes. The engine reports no 2P from a failing best case.'),
  ('prms', 'intermediate', 'module', 'm04-the-economic-limit', 9, 'The golden input econ-faq33-low-fails states low, best and high of 5000000, 7000000 and 9000000 barrels in one year at 10 a barrel against capital of 60000000. Which 1P and 2P does the engine report?', '["2P 7000000.000000, with 1P set to 0.000000", "2P 7000000.000000, with 1P at 5000000.000000", "2P 2000000.000000, with 1P set to 0.000000", "2P 7000000.000000, with 1C at 5000000.000000"]'::jsonb, 0, 'The low case returns -10000000.000000 and fails, the best returns 10000000.000000 and passes, so the project holds Reserves with 1P set to 0 and the whole best estimate as 2P (PRMS 3.1.2.8; FAQ 3.3). Reporting 5000000 as 1P books barrels that do not pay. A 2P of 2000000 takes the low barrels out of it. FAQ 3.4 keeps them out of 1C, since a project carries a single classification.'),
  ('prms', 'intermediate', 'module', 'm04-the-economic-limit', 10, 'When the low case fails and the best passes, where does the engine put the low-case barrels?', '["In the 1C of Contingent Resources beside the Reserves", "Out of every category, dropped with the failing case", "In the 1P, marked as not economic", "Inside the 2P, in the Probable (P2) increment"]'::jsonb, 3, 'The engine''s reason reads "the low case quantities remain within 2P; FAQ 3.4 keeps them out of 1C, since a project carries a single classification". On the FAQ 3.3 figures the Probable (P2) is 7000000.000000, the whole best estimate, so the low barrels sit inside it. Splitting them into 1C would give one project two classes. They are dropped from no category they belong to, and the 1P is 0.'),
  ('prms', 'intermediate', 'module', 'm04-the-economic-limit', 11, 'On the same FAQ 3.3 figures, what Possible (P3) increment does the engine return?', '["9000000.000000", "2000000.000000", "7000000.000000", "0.000000"]'::jsonb, 1, 'The Possible (P3) is the 3P less the 2P, 9000000.000000 less 7000000.000000, which the engine returns as 2000000.000000. 9000000.000000 is the cumulative 3P. 7000000.000000 is the Probable (P2) here. A failing low case sets the 1P to 0 and leaves the 2P and 3P, and so the Possible (P3), standing.'),
  ('prms', 'intermediate', 'module', 'm04-the-economic-limit', 12, 'With the best case economic, the high forecast on the same costs and prices returns -5000000. What does the engine do?', '["Reports a 3P equal to the 2P and prints a warning beside it", "Sets the 3P to 0, as it sets the 1P when the low case fails", "Refuses forecasts.high, which must be economic when the best case is", "Swaps the best and high forecasts so the range is in order again"]'::jsonb, 2, 'A high forecast that loses money when the best makes money is no range, so the engine refuses it: "forecasts.high must be a forecast that is economic when the best case is (tested on the same costs and prices, PRMS 2.2.0.3: an undiscounted net cash flow above 0); got -5000000". Only the low case may fail while the best passes. The engine never rewrites or reorders a stated forecast.'),
  ('prms', 'intermediate', 'module', 'm04-the-economic-limit', 13, 'Handed the EKN-1 best case directly, with the same regime and inputs, computeCashFlow of cashflow.ts returns 2037 and an undiscounted net cash flow of 382377266.937500. What does that show?', '["The prms engine rounds the canonical figures to its own precision", "The prms engine applies the working interest before the cash flow runs", "The prms engine reports the canonical cash flow''s own figures", "They agree only with the licence cut off"]'::jsonb, 2, 'The engine carries no cash flow, NPV or discounting code of its own. Its basis reads "computeCashFlow of engines/economics/cashflow.ts with apply_economic_limit (JV regime at 100%, the stated royalty and tax), checked against PRMS 3.1.3.1", and the direct call returns the same limit, 3 years trimmed, the same net cash flow and the NPV 318649106.969712. It rounds nothing and runs at 100 percent before any share, and the match holds on the EKN-1 start itself, where the licence cut is in force.'),
  ('prms', 'intermediate', 'module', 'm04-the-economic-limit', 14, 'On EKN-1 the loss carry forward is set to false. What becomes of the best case''s undiscounted net cash flow?', '["It stays at 382377266.937500", "It falls to 267664086.856250", "It rises to 651707494.450000", "It is refused until a loss year appears"]'::jsonb, 0, 'The loss relief choice acts on the tax only, and on EKN-1 no case has a loss year to carry, so the best undiscounted net cash flow is 382377266.937500 either way (golden input econ-ekene-no-loss-relief). 267664086.856250 is the best case at the 70.000000 percent working interest, and 651707494.450000 is the high case. The choice is a stated true or false and is accepted as false.'),
  ('prms', 'intermediate', 'module', 'm04-the-economic-limit', 15, 'On the EKN-1 net-entitlement start, the discount rate is changed from 10.000000 percent to 0. What moves?', '["Every economic limit, since the trim reads discounted cash", "The 2P and nothing else", "The verdicts, since the economic test is run on the NPV", "The NPV columns alone"]'::jsonb, 3, 'The discount rate sets the NPV and nothing else: the economic test is undiscounted (PRMS 3.1.2.1), and the trailing trim reads revenue less royalty less opex year by year. So the limits, the verdicts and every Reserves quantity stay, and at 0 each NPV equals its undiscounted net cash flow. An NPV is always quoted with its rate.'),
  ('prms', 'intermediate', 'module', 'm05-entitlement-and-the-reporting-basis', 1, 'EKN-1 carries a 70.000000 percent working interest and a 15.000000 percent royalty stated as a royalty interest. On the working-interest basis, what 2P in BOE does the engine report?', '["13211487.916667 BOE", "18873554.166667 BOE", "11229764.729167 BOE", "19825024.800000 BOE"]'::jsonb, 0, 'On the working-interest basis the engine scales the gross quantities by the stated 70.000000 percent through the canonical applyJV of cashflow.ts, giving a 2P of 13211487.916667 BOE (golden input econ-ekene-working-interest). 18873554.166667 is the gross 2P. 11229764.729167 is the net-entitlement 2P, which also removes the royalty interest. 19825024.800000 is the 3P on the working-interest basis.'),
  ('prms', 'intermediate', 'module', 'm05-entitlement-and-the-reporting-basis', 2, 'Read the net-entitlement start of the Ekene Main waterflood, royalty stated as an interest in production. Which cumulative 2P oil figure does it print?', '["11657195.200000 barrels", "16653136.000000 barrels", "9908615.920000 barrels", "4618647.040000 barrels"]'::jsonb, 2, 'Net entitlement takes the working-interest share and removes the royalty interest, and the engine''s line reads "net entitlement: 70% working interest less the 15% royalty interest (PRMS 3.3.1.1)"; the 2P oil is 9908615.920000. 11657195.200000 is the working-interest 2P oil, before the royalty comes out. 16653136.000000 is the gross 2P oil. 4618647.040000 is the increment above the 1P, and the question asks for the cumulative 2P.'),
  ('prms', 'intermediate', 'module', 'm05-entitlement-and-the-reporting-basis', 3, 'The same EKN-1 royalty is restated as a production tax, still on the net-entitlement basis. What 2P in BOE comes back, and how does it compare?', '["11229764.729167, since the 15.000000 percent still leaves the volumes", "13211487.916667, exactly the working-interest figure", "18873554.166667, the gross figure", "Half-way between the two"]'::jsonb, 1, 'A production tax is paid in money, so no volume is deducted (PRMS 3.3.1.2), and the net entitlement then prints the same figures as the working interest: 13211487.916667 BOE, checked equal exactly (golden inputs econ-ekene-production-tax and econ-ekene-working-interest). 11229764.729167 is the royalty-interest reading. The working interest of 70.000000 percent still applies, so the gross figure is out of reach, and the engine splits no volume in half.'),
  ('prms', 'intermediate', 'module', 'm05-entitlement-and-the-reporting-basis', 4, 'Which net entitlement line does the engine print when the EKN-1 royalty is stated as a production tax?', '["net entitlement: 70% working interest less the 15% royalty interest (PRMS 3.3.1.1)", "net entitlement: the 70% working interest less 15 points of production tax", "net entitlement: 100% of the gross, since a production tax is paid by the buyer", "net entitlement: 70% working interest; the 15% payment is a production tax, so no volume is deducted (PRMS 3.3.1.2)"]'::jsonb, 3, 'The engine names the form it applies. With a production tax it takes out no volume and says so, citing PRMS 3.3.1.2. The line with "less the 15% royalty interest" is printed for the royalty-interest form. The engine subtracts no percentage points from the working interest, and a production tax leaves the working interest of 70 percent in place.'),
  ('prms', 'intermediate', 'module', 'm05-entitlement-and-the-reporting-basis', 5, 'On EKN-1, the royalty form changes from royalty interest to production tax. What happens to the best case''s undiscounted net cash flow at 100 percent?', '["It rises, as no volume is charged", "It falls, since the tax is charged on top of the royalty", "Nothing: it is 382377266.937500 under both forms", "No figure at all: it is refused until the rate is restated"]'::jsonb, 2, 'The form changes the volumes and leaves the money alone: the royalty is paid at the same 15.000000 percent either way, and the canonical cash flow charges it the same way, so the best case is 382377266.937500 under both forms and every economic limit stays. No second charge is made, and the form is a stated word that needs no restated rate.'),
  ('prms', 'intermediate', 'module', 'm05-entitlement-and-the-reporting-basis', 6, 'The EKN-1 2P on the net-entitlement basis is 9908615.920000 barrels of oil and 7926892.855000 Mscf of gas, with 6.000000 Mscf per BOE stated. What 2P in BOE does the engine report?', '["11229764.729167", "9908615.920000", "13211487.916667", "7926892.855000"]'::jsonb, 0, 'BOE counts a barrel of oil as one and converts the gas at the stated factor, so the 2P is the oil plus the gas over 6, which the engine returns as 11229764.729167. Supplementary does not mean the gas is left out. 13211487.916667 is the working-interest 2P in BOE, a different basis. The gas alone in Mscf is no BOE figure.'),
  ('prms', 'intermediate', 'module', 'm05-entitlement-and-the-reporting-basis', 7, 'Why does the engine call its BOE figures supplementary and cite PRMS 3.2.9.3?', '["BOE is the unit in which the Reserves categories are first decided and set", "The gas is valued at the oil price once it is converted to BOE", "BOE figures are reported only when the gas is sold under contract", "The factor is a heating-value convention that says nothing about price"]'::jsonb, 3, 'A barrel of oil and six Mscf of gas rarely sell for the same money, so the BOE is given beside the oil and the gas in their own units, with its factor stated. The cash flow prices each product at its own stated price. The engine uses BOE to check that the three cases stay in order, and it reports BOE on every call whatever the gas contract.'),
  ('prms', 'intermediate', 'module', 'm05-entitlement-and-the-reporting-basis', 8, 'The Mscf per BOE control is set to 0. Which message does the engine return?', '["The oil alone in BOE", "Refused on mscfPerBoe, with 0 printed back", "mscfPerBoe must be a finite number above 0; got nothing", "An unknown-key refusal"]'::jsonb, 1, 'A factor of 0 would divide by nothing, so it is refused with the value printed as given, 0. The message ending "got nothing" belongs to a factor left out altogether. The engine never drops the gas silently, and mscfPerBoe is an accepted key of economicLimit.'),
  ('prms', 'intermediate', 'module', 'm05-entitlement-and-the-reporting-basis', 9, 'The EKN-1 best case returns 382377266.937500 undiscounted at 100 percent. What does the engine report at the stated 70.000000 percent working interest?', '["382377266.937500", "223054374.878798", "267664086.856250", "318649106.969712"]'::jsonb, 2, 'The engine runs the cash flow once at 100 percent and scales the undiscounted net cash flow and the NPV by the stated working interest through applyJV, so the best case is 267664086.856250 at 70.000000 percent. The engine reports both the 100 percent and the share columns. 223054374.878798 and 318649106.969712 are NPVs at 10.000000 percent, at the share and at 100 percent.'),
  ('prms', 'intermediate', 'module', 'm05-entitlement-and-the-reporting-basis', 10, 'Why does the engine scale the cash by the working interest alone, with no royalty taken out a second time?', '["The canonical ledger already charges the royalty before tax", "The royalty applies to volumes alone and stays out of every cash flow", "The royalty is charged only when the form is a production tax", "Net entitlement is a gross basis, so no share is taken"]'::jsonb, 0, 'The royalty is already in the cash flow: the canonical ledger charges it as a cost of production before any tax, whichever form is stated. Net entitlement takes the royalty out of the volumes for reporting, and scaling the cash by the net entitlement share would charge the royalty holder''s share twice. The ledger charges it under both forms, and net entitlement is a share basis.'),
  ('prms', 'intermediate', 'module', 'm05-entitlement-and-the-reporting-basis', 11, 'Why are the economic limits and verdicts of EKN-1 the same on the gross, working-interest and net-entitlement bases?', '["One stored limit is copied to each basis", "The cash flow and the test run at 100 percent before any scaling", "The limits move with the basis, and they only look alike at 70 percent", "Each basis is tested at its own share, and all three happen to pass"]'::jsonb, 1, 'The economic test and the canonical economic limit of each case are run on the whole project, and the basis is applied only to the kept quantities afterwards, so the low, best and high limits stay at 2033, 2037 and 2040 on every basis. A project either pays or does not, and the company''s share of it does not change that.'),
  ('prms', 'intermediate', 'module', 'm05-entitlement-and-the-reporting-basis', 12, 'A working interest of 0 is stated. What does the engine return?', '["Zero Reserves on every basis, with the project still tested at 100 percent", "The gross figures, since a working interest of 0 reads as not stated", "workingInterestPct must be stated; got nothing", "It refuses workingInterestPct, which must lie above 0 and at most 100"]'::jsonb, 3, 'The engine''s message reads "workingInterestPct must be a number above 0 and at most 100; got 0". A company holding no share of the project has nothing of it to report. A refusal returns no figures, and 0 is a stated value, which the engine reads as stated; a working interest left out draws the same refusal ending "got nothing".'),
  ('prms', 'intermediate', 'module', 'm05-entitlement-and-the-reporting-basis', 13, 'A box states reportingBasis as "net". What is refused, and how?', '["reportingBasis, which must be one of \"gross\", \"working-interest\", \"net-entitlement\"", "Nothing: \"net\" is read as net entitlement and the figures are printed", "royalty.form, which must change to production-tax for a net basis", "workingInterestPct, which a net basis needs stated as 100"]'::jsonb, 0, 'The basis is stated with the words the engine reads, and anything else is refused, verbatim: "reportingBasis must be one of "gross", "working-interest", "net-entitlement"; got "net"". The engine maps no near-match onto an accepted word. The royalty form and the working interest are separate stated inputs that the basis does not constrain.'),
  ('prms', 'intermediate', 'module', 'm05-entitlement-and-the-reporting-basis', 14, 'A royalty of 100 percent is stated. Which field does the engine refuse?', '["royalty.form, which must become production-tax at 100", "workingInterestPct, which must fall to 0 with the royalty", "royalty.ratePct, which must be from 0 to below 100", "None: the engine returns each of its figures as 0.000000"]'::jsonb, 2, 'The rate is stated as a percent from 0 up to, but short of, 100, and the engine refuses 100 with the message "royalty.ratePct must be a number from 0 to below 100; got 100". A full royalty would hand every barrel to the royalty holder. The form is a separate stated word and the working interest a separate stated percent, and neither is touched. A refused call prints no figures.'),
  ('prms', 'intermediate', 'module', 'm05-entitlement-and-the-reporting-basis', 15, 'On the working-interest basis, the working interest is set to 100 and nothing else moves. What 2P oil does the engine report?', '["11657195.200000, still the 70.000000 percent share", "16653136.000000, the gross figure", "9908615.920000, since the royalty interest still comes out", "18252916.000000, the technical forecast"]'::jsonb, 1, 'At 100 percent the working-interest scaling takes nothing away, so the working-interest basis equals the gross: 16653136.000000 barrels, the best case to its economic limit. 11657195.200000 is the 70 percent share. The royalty interest comes out only on the net-entitlement basis. The technical best case is the forecast before the licence and limit cuts.'),
  ('prms', 'intermediate', 'module', 'm06-licence-expiry-and-time', 1, 'The Ekene petroleum mining lease is stated to expire in 2040 with no renewal expected, and every EKN-1 forecast runs to 2041. How much high-case oil does the engine report beyond the licence?', '["308309.000000 barrels", "98956.000000 barrels", "0.000000 barrels", "601257.000000 barrels"]'::jsonb, 3, 'The licence cut removes 2041 from each case, and the high case loses 601257.000000 barrels to it; the best loses 308309.000000 and the low 98956.000000. A case that is still paying is cut all the same, because the cut comes before the cash flow runs whenever no renewal is expected.'),
  ('prms', 'intermediate', 'module', 'm06-licence-expiry-and-time', 2, 'The golden input econ-ekene-renewal-expected differs from the EKN-1 start only in stating a renewal as expected. What 3P in BOE does it report on the net-entitlement basis?', '["17256718.756667", "16851271.080000", "28321464.000000", "19825024.800000"]'::jsonb, 0, 'With a renewal expected the whole forecast runs, the high case reaches its economic limit in 2041, nothing is beyond the licence, and the 3P rises to 17256718.756667 BOE. 16851271.080000 is the 3P with the licence cut in 2040. 28321464.000000 and 19825024.800000 are the 3P on the gross and working-interest bases, and this input reports net entitlement.'),
  ('prms', 'intermediate', 'module', 'm06-licence-expiry-and-time', 3, 'On that renewal-expected input, the 2P stays at 11229764.729167 BOE. Why does the renewal leave it alone?', '["A renewal is applied to the high forecast only by rule", "The 2P is always cut at the licence whatever is stated", "The best case stops paying in 2037, before the expiry", "The engine holds the 2P fixed and moves the 3P to match"]'::jsonb, 2, 'Each case is cut at its own canonical economic limit, and the best case reaches it in 2037, three years before the 2040 expiry, so the years a renewal restores add nothing to it. The renewal applies to every case alike; it matters only for a case that would still pay after the expiry. A stated renewal removes the licence cut from the 2P as well, and the engine computes each category from its own case.'),
  ('prms', 'intermediate', 'module', 'm06-licence-expiry-and-time', 4, 'On the EKN-1 start with no renewal, which case has the licence as the thing that stops it?', '["The low case, whose limit of 2033 falls well before the expiry", "The high case, whose economic limit is the expiry year 2040", "The best case, whose limit of 2037 is set by the licence", "All three alike, since each loses its 2041 row"]'::jsonb, 1, 'The high case would still pay after 2040, so its limit is the expiry year itself, 2040, with 0 trailing years cut. The low and best cases stop paying first, in 2033 and 2037, so the trailing trim ends them well inside the licence. Every case loses 2041 to the licence, and only the high case would otherwise have produced at a profit then.'),
  ('prms', 'intermediate', 'module', 'm06-licence-expiry-and-time', 5, 'A licence expires in 2040. Which year is the first one the no-renewal cut removes?', '["2041: the expiry year itself stays inside the licence", "2040, the year the right to operate ends", "The year before the expiry, the last full one", "None: the licence is read only by the economic test"]'::jsonb, 0, 'The cut removes the years after the stated expiry, and the expiry year produces as the forecast says. On EKN-1 each case loses 2041 alone. Cutting 2040 or the year before it would remove years the licence covers. The licence cut is applied to the forecast before the cash flow runs, ahead of the economic limit and the test.'),
  ('prms', 'intermediate', 'module', 'm06-licence-expiry-and-time', 6, 'The golden input econ-refuse-capex-after-licence states a licence expiring in 2030, no renewal expected, and a capital row in 2031. What comes back?', '["The capital moved to 2030, the last year inside the licence", "The capital dropped with the cut years and the rest computed", "A renewal read as expected, since capital is planned after the expiry", "costs.capex[0].year must be at most 2030, the licence expiry, when no renewal is expected; got 2031"]'::jsonb, 3, 'Capital after the expiry would be spent in a period with no right to operate, on barrels the engine has already removed, so it refuses and names the row, the expiry and the condition. It never moves or drops the capital or guesses the renewal, since each would change a Reserves figure by a choice the caller did not make.'),
  ('prms', 'intermediate', 'module', 'm06-licence-expiry-and-time', 7, 'A second capital row for 2027 is added beside the first. How does the engine treat the pair?', '["It adds the two rows together and runs the canonical cash flow on their sum", "It refuses costs.capex[1].year: a year no other capex row has", "It keeps the first row for 2027 and silently drops the second one it finds", "It moves the second row on to 2028, the next free year"]'::jsonb, 1, 'Two rows for one year would leave the engine to decide how to combine them, so it refuses the later row with the message "costs.capex[1].year must be a year no other capex row has; got 2027". It sums, drops and moves nothing, since each of those would be a choice the caller did not make.'),
  ('prms', 'intermediate', 'module', 'm06-licence-expiry-and-time', 8, 'On EKN-1, effective 2027, the licence expiry is stated as 2026. What is the result?', '["Every forecast year cut, with 0.000000 barrels of Reserves left in each of the three cases", "The expiry moved to 2027, the effective year", "A refusal: licence.expiryYear must be an integer from 2027 to 2300", "The whole forecast run, since the expiry has already passed"]'::jsonb, 2, 'A licence must run at least to the effective year, so the engine refuses: "licence.expiryYear must be an integer from 2027 to 2300; got 2026". It returns no figures from a refused input, rewrites no stated year, and reads no past expiry as a renewal.'),
  ('prms', 'intermediate', 'module', 'm06-licence-expiry-and-time', 9, 'The renewal control is set to not stated. What does the engine print?', '["The figures with no renewal, the cautious reading of a blank", "The figures with a renewal, since the forecast runs past the expiry", "licence.expiryYear must be an integer from 2027 to 2300; got nothing", "A refusal naming licence.renewalExpected, a stated fact with no default"]'::jsonb, 3, 'The engine''s message reads "licence.renewalExpected must be true or false (stated; no default); got nothing". A missing renewal expectation is refused by name. The engine assumes neither answer, since either would move the 3P on EKN-1. The expiry year is still stated on this input, so the refusal names the renewal field.'),
  ('prms', 'intermediate', 'module', 'm06-licence-expiry-and-time', 10, 'Where does the engine put the barrels it reports beyond the licence?', '["Nowhere: it reports them and classifies none of them", "In the 3P, since they may be produced under a renewal", "In Contingent Resources, as a 1C of the same project", "Out of the report, with no figure printed for them"]'::jsonb, 0, 'PRMS 3.3.3.2, which answer 4.4 of the PRMS FAQs cites, places such quantities in Contingent Resources unless an extension is reasonably expected; the engine''s call covers one Reserves project, so it reports the barrels beyond the licence and leaves the Contingent quantity for the estimator to state as a project of its own. A project carries a single classification, and the figure is printed for every case.'),
  ('prms', 'intermediate', 'module', 'm06-licence-expiry-and-time', 11, 'For US filers, what does 17 CFR 210.4-10(a)(22) (the eCFR current at 2026-09-01) ask before proved reserves may run past the expiry of the right to operate?', '["A reasonable expectation of renewal, as the PRMS asks", "A renewal that has already been granted in writing by the regulator", "Evidence indicating that renewal is reasonably certain", "Nothing: proved reserves always stop at the expiry"]'::jsonb, 2, 'The rule ends proved reserves "prior to the time at which contracts providing the right to operate expire, unless evidence indicates that renewal is reasonably certain," (17 CFR 210.4-10(a)(22)). The PRMS test is a reasonable expectation, a weaker one. The SEC text asks for evidence of reasonable certainty, and it lets proved reserves run past the expiry when that evidence exists.'),
  ('prms', 'intermediate', 'module', 'm06-licence-expiry-and-time', 12, 'The low forecast of EKN-1 reaches its economic limit in 2033. Which years does each rule remove from it?', '["The licence takes every year after 2033, and the limit takes none of them", "The licence takes 2041; the limit takes the 7 years after 2033", "The limit takes 2041, and the licence takes all the years after 2033", "Both remove the same 8 years together"]'::jsonb, 1, 'The licence cut comes first and removes the year after the 2040 expiry, 2041; the canonical trailing trim then removes the 7 years after 2033 that stop paying. The two remove different years: the licence ends in 2040, and it is the trim that ends the low case in 2033.'),
  ('prms', 'intermediate', 'module', 'm06-licence-expiry-and-time', 13, 'The Petroleum Industry Act 2021 caps retention of a significant discovery at 10 years from the declaration (s.78(9)) and asks for a field development plan within 2 years of a commercial discovery declaration (s.79(1)). What part do these play in the economic limit calculation?', '["None: the engine prints them as notes beside a classification", "The 10 years become the licence expiry of any significant discovery", "The 2 years set the latest capital year the engine accepts", "They set the renewal expectation once the declaration is stated"]'::jsonb, 0, 'The Act''s clocks are carried as Nigerian notes on a classification, and none of them sets a licence expiry in the economic limit: the expiry and the renewal expectation are stated facts of the licence held. The capital check reads the stated expiry alone, and the renewal is a stated true or false.'),
  ('prms', 'intermediate', 'module', 'm06-licence-expiry-and-time', 14, 'On what basis is the oil beyond the licence reported?', '["On the stated reporting basis, like the categories", "At the working interest, the company''s share", "In BOE only, converted at the stated Mscf per BOE", "Gross, before any reporting basis is applied"]'::jsonb, 3, 'The engine reports the barrels beyond the licence gross, as it reports the technical, beyond-limit and economic gross quantities of each case; the stated basis is applied to the reported categories. So the high case shows 601257.000000 barrels beyond the licence whatever basis is stated, and in oil as well as BOE.'),
  ('prms', 'intermediate', 'module', 'm06-licence-expiry-and-time', 15, 'On a copy of EKN-1, the licence expiry is moved to 2041 with no renewal expected. What licence cut does the engine report?', '["2041 for every case, the expiry year itself", "None: every forecast ends in the expiry year", "2040 for every case, as on the start", "A refusal: expiry must fall before the last forecast year"]'::jsonb, 1, 'The cut removes the years after the stated expiry, and the forecasts end in 2041, so with an expiry in 2041 nothing lies beyond the licence and the licence cut column is empty for every case. The expiry year itself is kept. An expiry from 2027 to 2300 is accepted, and 2041 is well inside that range.'),
  ('prms', 'intermediate', 'final', null, 1, 'A commercial project moves from approved-for-development to on-production. Which stated fact changes to move it?', '["Its first sales begin, so onProduction becomes true", "Its final investment decision turns from false to true", "Its reserves status is restated as developed-producing first", "Its chance of development reaches 100 percent"]'::jsonb, 0, 'The Reserves sub-classes lie along one path: justified becomes approved when the investment decision is taken, and approved becomes on-production when production starts (PRMS 2.1.3.5, Table 1). An approved project already has its decision. A developed-producing status is open only once the project is on production, so it follows the change and cannot lead it. A Reserves project carries no chance at all.'),
  ('prms', 'intermediate', 'final', null, 2, 'A play states a chance of geologic discovery of 10.000000 percent and a chance of development of 50.000000 percent. What chance of commerciality comes back?', '["10.000000 percent", "50.000000 percent", "5.000000 percent", "None for a play"]'::jsonb, 2, 'Every Prospective sub-class carries the product Pc = Pg x Pd (PRMS 2.1.3.3), and the golden input class-play returns 5.000000 percent. Either chance alone leaves out the other. The sub-class records how much is known, and a play carries its chances like a prospect or a lead.'),
  ('prms', 'intermediate', 'final', null, 3, 'A copy of a Reserves project states chances.developmentPct as 95. What does the engine do?', '["Returns the class with a chance of commerciality of 95 percent", "Refuses chances, which must be left out for Reserves", "Returns Contingent Resources, since a chance below 100 means risk remains", "Ignores the stated chance and returns the class unchanged"]'::jsonb, 1, 'The engine''s message reads "chances must be left out for Reserves (PRMS 2.1.3.3 treats Reserves as near-certain to be commercial, so no chance figure is carried); got {"developmentPct":95}". No chance is carried for Reserves, the stated chance does not reopen the class, and the engine ignores no stated input silently.'),
  ('prms', 'intermediate', 'final', null, 4, 'On a copy of Ekene North appraisal (EKN-4), the whole chances object is removed. Which message comes back?', '["chances must be an object { developmentPct } for Contingent Resources (PRMS 2.1.3.3: Pc = Pd); got nothing", "Contingent Resources with a chance of commerciality of 0 and every blocker unchanged", "chances.geologicDiscoveryPct must be a number from 0 to 100; got nothing", "Contingent Resources with no chance printed, as for Reserves"]'::jsonb, 0, 'A Contingent project must state its chance of development, since its chance of commerciality is Pd alone, so a missing chances object is refused whole. The engine reads no missing chance as 0. A chance of geologic discovery belongs to an undiscovered project and is refused on this one. Only Reserves leave chances out.'),
  ('prms', 'intermediate', 'final', null, 5, 'Ekene West tight sand (EKN-5) states a chance of development of 20.000000 percent and the sub-class development-unclarified. What chance of commerciality does the engine print for it?', '["None: it is not viable", "65.000000 percent", "20.000000 percent", "10.500000 percent"]'::jsonb, 2, 'EKN-5 is discovered, so Pc = Pd and the engine returns 20.000000 percent (PRMS 2.1.3.3). A not-viable economic status is a blocker and removes no chance. 65.000000 percent is EKN-4''s Pd. A product of two chances applies to an undiscovered project, such as the Ekene Shallow lead with its 10.500000 percent.'),
  ('prms', 'intermediate', 'final', null, 6, 'In what order does the engine read the facts of a discovered project?', '["The stated sub-class first, and then only the criteria that the stated sub-class needs", "Reserves status first, then the project status, then the criteria", "The chance of development first, since it decides whether the criteria are read", "Class from the criteria first, then the facts that set a sub-class of that class"]'::jsonb, 3, 'The engine decides the class from the commerciality criteria, and only then reads the facts that set a sub-class of that class: a project status for Reserves, a stated sub-class for Contingent Resources. So a stated sub-class cannot make a project commercial, a project status is read for Reserves alone, and the reserves status is checked last against the project status. The chance of development sets the chance of commerciality and decides no class.'),
  ('prms', 'intermediate', 'final', null, 7, 'A justified-for-development project, with no investment decision and no production, states a reserves status. Which statuses does the engine accept?', '["developed-producing only, once every criterion is met", "undeveloped only, since no decision has been taken", "Any of the three, since the status is a stated fact", "developed-non-producing or undeveloped"]'::jsonb, 3, 'A justified project has no wells flowing to sales, so of the three statuses (PRMS 2.1.3.6, Table 2) it may carry the two that describe quantities yet to flow; the developed producing status waits for production. The engine does not tie the status to the investment decision, and a stated status is checked against the project status.'),
  ('prms', 'intermediate', 'final', null, 8, 'Which criteria does the engine name as holding back Ekene West tight sand (EKN-5)?', '["developmentPlan, financialAppropriations, approvals, firmIntention", "technology under development, developmentPlan, financialAppropriations, economicStatus, firmIntention", "economicStatus alone, since its status is stated as not-viable", "financialAppropriations, timeFrame, economicStatus, market, facilities, firmIntention"]'::jsonb, 1, 'EKN-5''s class decision reads "Contingent Resources: not commercial (technology under development, developmentPlan, financialAppropriations, economicStatus, firmIntention)". The four-item list is Ekene North appraisal''s and the six-item list Ekene East gas''s. A not-viable status is one blocker of five on EKN-5, and the recovery project on technology under development is another.'),
  ('prms', 'intermediate', 'final', null, 9, 'A project starting development within 6 years, with no justification stated for the longer wait, states the sub-class approved-for-development. What does the refusal show?', '["It names subClass and prints timeFrame as the reason the project is not commercial", "It names projectStatus, since an approved project must state its investment decision too", "It names commerciality.timeFrame, which must fall at or below 5 years", "It names subClass and lists the six blockers of Ekene East gas"]'::jsonb, 0, 'The engine decides the class first: the time-frame fails, so the project is Contingent Resources, and a Reserves sub-class is refused with "(not commercial: timeFrame)" in the message beside the four Contingent sub-classes. The start of 6 is a valid input. The six-blocker message belongs to a different golden input, and the field the refusal names is subClass.'),
  ('prms', 'intermediate', 'final', null, 10, 'The same 6-year project instead states a project status with the investment decision taken. Which field is refused?', '["subClass, which must become approved-for-development", "commerciality.timeFrame.longerJustified, which the decision implies", "projectStatus, since a Contingent project leaves it out", "None: a decision taken turns the project into Reserves"]'::jsonb, 2, 'The engine''s message reads "projectStatus must be left out for Contingent Resources (the project status that sets a Reserves sub-class, PRMS 2.1.3.5); got {"finalInvestmentDecision":true,"onProduction":false}". The criteria decide the class, and a taken decision neither justifies the wait nor makes the project commercial.'),
  ('prms', 'intermediate', 'final', null, 11, 'How does the engine hold the five-year benchmark of the time-frame criterion?', '["As a rule of the Petroleum Industry Act 2021, cited to its section on field development plans", "As the SEC''s five years for proved undeveloped reserves, cited to 17 CFR 229.1203(d)", "As PRMS_FIGURES.reasonableTimeFrameYears, 5, a recommended benchmark cited to PRMS 2.1.2.3 and 2.1.3.6.4", "As a panel setting the learner may change in place of the stated start"]'::jsonb, 2, 'The engine holds five figures, each with its citation, and the benchmark is one: PRMS 2.1.2.3 and 2.1.3.6.4, a recommended benchmark of the standard. The Act''s figure for a field development plan is 2 years (s.79(1)). The SEC''s five years is a disclosure rule the engine does not carry. The start and its justification are the stated facts; the benchmark is fixed with its source.'),
  ('prms', 'intermediate', 'final', null, 12, 'Regulation S-K Item 1203 (the eCFR current at 2026-09-01), paragraph (d), carries a five-year figure too. What does it require of a filer?', '["To book no proved undeveloped reserves whose development starts later than five years out", "To explain why material proved undeveloped reserves remain undeveloped for five years or more after disclosure", "To add every field''s estimates arithmetically when it reports its proved reserves", "To state a firm intention to proceed before any reserves are disclosed"]'::jsonb, 1, 'The text reads "(d) Explain the reasons why material amounts of proved undeveloped reserves in individual fields or countries remain undeveloped for five years or more after disclosure as proved undeveloped reserves." (17 CFR 229.1203(d)). It is a disclosure rule for filed reserves, and the engine applies the PRMS benchmark and carries no SEC time-frame rule. The arithmetic-sum rule is 229.1202(a)(3), and the firm intention is a PRMS criterion.'),
  ('prms', 'intermediate', 'final', null, 13, 'On a copy of Ekene East gas (EKN-3), the market and facilities criteria are set to true. Which blockers remain?', '["financialAppropriations, timeFrame, economicStatus, firmIntention", "firmIntention alone, since the gas now has a buyer and a pipeline", "None: a gas project needs only a market and facilities to be Reserves", "financialAppropriations, timeFrame, firmIntention, the status being met"]'::jsonb, 0, 'Setting the two outward criteria true clears two of EKN-3''s six blockers and leaves the money, the time-frame, the economic status and the commitment unmet, so the class stays Contingent Resources. The economic status is stated undetermined, and only viable meets criterion (4). Every criterion and the commitment must be met for Reserves.'),
  ('prms', 'intermediate', 'final', null, 14, 'The Petroleum Industry Act 2021 defines a commercial discovery by the licensee''s own judgement (s.318). How does the engine use a stated Nigerian declaration?', '["As the eighth commerciality criterion, in place of the firm intention", "As the class itself: a commercial discovery is read as Reserves", "As a note printed beside the class, which moves no class", "As the sub-class of a Contingent project"]'::jsonb, 2, 'The declaration is the licensee''s statement to the Commission, and the engine prints it as a note beside the PRMS class. It refuses a note that contradicts a commercial project, keeping the two consistent, and lets neither change the class. The firm intention stays its own stated fact, and the sub-classes are the PRMS ones.'),
  ('prms', 'intermediate', 'final', null, 15, 'The golden input cat-contingent-cumulative gives 1C, 2C and 3C of 3.000000, 4.500000 and 6.500000. Which third increment comes back?', '["6.500000", "1.500000", "2.000000", "4.500000"]'::jsonb, 2, 'C3 is the 3C less the 2C, 6.500000 less 4.500000, and the engine returns 2.000000 (golden input cat-contingent-cumulative), the same as when the set is stated incrementally. 6.500000 is the cumulative 3C. 1.500000 is the C2. 4.500000 is the 2C, a cumulative figure.'),
  ('prms', 'intermediate', 'final', null, 16, 'The golden input cat-prospective states 12, 30 and 70 MMbbl cumulatively. What does the engine return?', '["1U, 2U and 3U, each followed by the increment above the one before", "1P, 2P and 3P of 12.000000, 30.000000 and 70.000000", "1U, 2U and 3U of 12.000000, 30.000000 and 70.000000, with no increments", "A refusal, since Prospective Resources carry no categories of their own at all"]'::jsonb, 2, 'Prospective Resources carry the categories 1U, 2U and 3U and no incremental terms (PRMS 2.2.2.4), and the engine''s reason says so. The labels 1P, 2P and 3P belong to Reserves. The cumulative method is the one Prospective sets accept, so the call returns categories.'),
  ('prms', 'intermediate', 'final', null, 17, 'On EKN-1''s net-entitlement categories, the 3P oil is 14868768.565000 and the 2P oil 9908615.920000. What Possible (P3) oil does the engine report?', '["14868768.565000 barrels, the 3P", "4960152.645000 barrels", "4618647.040000 barrels, the slice below it", "5621506.350833, the Possible (P3) in BOE"]'::jsonb, 1, 'The Possible (P3) is the 3P less the 2P, which the engine returns as 4960152.645000 barrels of oil. 14868768.565000 is the cumulative 3P. 4618647.040000 is the Probable (P2) oil. 5621506.350833 is the same increment in BOE, which adds the gas.'),
  ('prms', 'intermediate', 'final', null, 18, 'On EKN-1''s net-entitlement BOE rows, how does the Proved (P1) compare with the 1P?', '["They are the same figure, 5995298.044167", "The Proved (P1) is smaller, being a slice of the 1P", "The Proved (P1) is 5234466.685000, the slice above the 1P", "They differ: the Proved (P1) is blank, since increments start at P2"]'::jsonb, 0, 'The first increment is the 1P itself: 1P = P1, and the engine prints both rows at 5995298.044167 BOE. 5234466.685000 is the Probable (P2), the slice between the 1P and the 2P. The engine prints all three increments, P1 included.'),
  ('prms', 'intermediate', 'final', null, 19, 'Under the course''s vocabulary, what does "proved" alone mean?', '["The increment Proved (P1), whatever the form of the set", "Any quantity shown to be true by a well test", "The 2P, which a reserves report treats as its headline", "The cumulative 1P, the low estimate of Reserves"]'::jsonb, 3, 'Proved alone is the cumulative 1P; the increment is always written Proved (P1), and the same pattern holds for probable (2P, P2) and possible (3P, P3). In conversation proved can mean shown to be true, and the course narrows it. The 2P is the best estimate, the probable category in cumulative form.'),
  ('prms', 'intermediate', 'final', null, 20, 'Why does the engine accept a Proved (P1) of 0 and refuse a Probable (P2) of -1?', '["A zero is read as not stated at all, and a negative figure as a simple typing slip", "Only the first increment may be 0, and every later increment must lie strictly above it", "A negative increment is accepted only for Contingent Resources", "A zero slice states nothing at that confidence; a negative one breaks the order"]'::jsonb, 3, 'Zero is a statement about the evidence: nothing is confident enough to be called proved, and 1P, 2P and 3P of 0.000000, 7.000000 and 7.000000 come back for the golden zero. A negative slice would make a cumulative category smaller than the one below it, and every increment of every class must be at or above 0. The engine reads a stated 0 as stated.'),
  ('prms', 'intermediate', 'final', null, 21, 'EKN-1''s increments come from three forecasts cut at three different limit years. Why are they still exact differences?', '["The engine first cuts all three forecasts back to one common limit year", "The engine subtracts the three cut quantities as cumulative estimates", "The increments are rounded to six decimals before they are added", "The engine rebuilds the cases from the increments afterwards"]'::jsonb, 1, 'Each case is cut at its own economic limit and put on the stated basis, and the engine then takes the three kept quantities as the 1P, 2P and 3P and subtracts, so P2 = 2P less 1P and P3 = 3P less 2P hold exactly. No common year is used, the engine rounds nothing it computes, and it builds the increments from the cases.'),
  ('prms', 'intermediate', 'final', null, 22, 'Does the EKN-1 low case pass the economic test, and on what figure?', '["147205926.399797, which passes", "109849540.263750, which passes", "156927914.662500, which fails", "156927914.662500, which passes"]'::jsonb, 3, 'The low case keeps 2027 to 2033 and returns 156927914.662500 undiscounted at 100 percent, above 0, so it is economic. 147205926.399797 is its NPV at 10.000000 percent, and 109849540.263750 its undiscounted figure at the 70.000000 percent working interest. A figure above 0 passes the test.'),
  ('prms', 'intermediate', 'final', null, 23, 'The trailing trim ends the EKN-1 best forecast in 2037. What volume of oil falls in the trimmed years?', '["1291471.000000 barrels", "308309.000000 barrels", "1864516.000000 barrels", "0.000000 barrels"]'::jsonb, 0, 'The best case reaches its limit in 2037 with 3 trailing years cut, and the engine reports 1291471.000000 barrels beyond the limit. 308309.000000 is the best case''s oil beyond the licence, a different cut. 1864516.000000 is the low case''s oil beyond the limit. The high case is the one that loses nothing to the limit.'),
  ('prms', 'intermediate', 'final', null, 24, 'Starting from 10854176.000000 technical barrels, what economic oil, gross, is left in the low forecast once the licence and the limit have cut it?', '["8890704.000000 barrels", "10854176.000000 barrels, before any cut", "5289968.880000 barrels, net of the royalty interest", "7112563, its gas in Mscf"]'::jsonb, 0, 'The technical low forecast of 10854176.000000 barrels loses 98956.000000 to the licence and 1864516.000000 to the limit, leaving 8890704.000000 barrels of economic oil, gross. 5289968.880000 is the same case on the net-entitlement basis, the 1P oil. 7112563 is the low case''s gas within the limit, in Mscf, as its reason prints it.'),
  ('prms', 'intermediate', 'final', null, 25, 'A price table for EKN-1 arrives with one row missing. Which message comes back?', '["The cash flow run on 14 years, with 2041 left out", "prices must be one flat price for the whole forecast; got 14 rows", "forecasts.best must have 14 rows to match the prices; got 15", "prices must have 15 rows, one a year from 2027 to 2041; got 14"]'::jsonb, 3, 'Each case, the prices and the opex must have one row a year from the effective year, in order, and a short table is refused before any arithmetic, since a missing year would otherwise vanish from the sums. The engine shortens no forecast to fit the prices, and a price is stated per year.'),
  ('prms', 'intermediate', 'final', null, 26, 'The tax block is removed from EKN-1. What does the engine return?', '["The cash flow run with no tax, since the royalty alone is stated", "tax.ratePct must be a number from 0 to below 100; got nothing", "tax must be an object { ratePct, depreciationYears, lossCarryforward }; got nothing", "The Reserves figures on the stated basis, with the tax line left blank"]'::jsonb, 2, 'The tax is a stated input with no default, and the whole block is refused when it is missing, with the three keys it needs named. The engine runs no cash flow without it and prints no Reserves figure from a refused call. The message names the block itself because the block as a whole is absent.'),
  ('prms', 'intermediate', 'final', null, 27, 'On the golden input econ-faq33-low-fails, what does the high case return?', '["10000000.000000 undiscounted, economic", "30000000.000000 undiscounted, economic", "-10000000.000000 undiscounted, which fails the test", "9000000.000000 undiscounted, economic"]'::jsonb, 1, 'The high case''s 9000000 barrels at 10 a barrel against capital of 60000000 give 30000000.000000, above 0. 10000000.000000 is the best case and -10000000.000000 the low case, which fails. 9000000.000000 is the high case''s reported oil, the 3P, in barrels.'),
  ('prms', 'intermediate', 'final', null, 28, 'Which step comes first when the engine works a technical forecast?', '["Cutting the years after the licence expiry when no renewal is expected", "Running the canonical cash flow over the whole forecast, every year included", "Finding the economic limit year of each case by the canonical trailing trim", "Scaling the barrels to the stated reporting basis"]'::jsonb, 0, 'The engine works five steps in order: the licence cut, the canonical cash flow at 100 percent, the years kept up to the economic limit, the economic test, and the Reserves categories on the stated basis. So the cash flow never sees the years beyond an expiry with no renewal, and the basis is applied last.'),
  ('prms', 'intermediate', 'final', null, 29, 'The first row of the low forecast states -1 barrels of oil. What does the engine return?', '["A refusal on forecasts.low[0].oil, which prints the -1 back", "The low case run with the row read as 0 barrels", "forecasts.low must be ordered at or below the best forecast, row by row; got -1", "The low case marked not economic, with 1P set to 0"]'::jsonb, 0, 'A forecast cannot hold a negative quantity, and the engine''s message reads "forecasts.low[0].oil must be a finite number at or above 0; got -1". It rewrites no stated figure to 0. No order check between forecasts is involved here, and a refused input gives no economic verdict.'),
  ('prms', 'intermediate', 'final', null, 30, 'On the gross basis, what 1P in BOE does EKN-1 report?', '["5995298.044167", "10076131.166667", "7053291.816667", "18873554.166667"]'::jsonb, 1, 'Gross is the whole project at 100 percent, and the low case''s economic quantities give a 1P of 10076131.166667 BOE (golden input econ-ekene-gross). 5995298.044167 is the net-entitlement 1P and 7053291.816667 the working-interest 1P. 18873554.166667 is the gross 2P.'),
  ('prms', 'intermediate', 'final', null, 31, 'Discounted at the stated 10.000000 percent and scaled to the operator''s share, what is the EKN-1 best case worth?', '["318649106.969712", "267664086.856250", "345104722.339947", "223054374.878798"]'::jsonb, 3, 'The best NPV at 100 percent is 318649106.969712, and applyJV multiplies it by the operator''s share to give 223054374.878798. The undiscounted best share, 267664086.856250, carries no discounting, and 345104722.339947 belongs to the high forecast.'),
  ('prms', 'intermediate', 'final', null, 32, 'Undiscounted, what is the EKN-1 high case worth to the 70.000000 percent partner?', '["651707494.450000", "345104722.339947", "456195246.115000", "267664086.856250"]'::jsonb, 2, 'Taken whole, the high case returns 651707494.450000 before discounting, and the partner''s 70 percent of it is 456195246.115000. 345104722.339947 discounts that share at 10 percent, and 267664086.856250 is what the best forecast gives the partner.'),
  ('prms', 'intermediate', 'final', null, 33, 'Which royalty form takes volume out of the net entitlement, and under which section?', '["The production tax, under PRMS 3.3.1.2", "Both forms alike, under PRMS 3.3.1", "Neither form: net entitlement is the working interest", "The royalty interest, under PRMS 3.3.1.1"]'::jsonb, 3, 'A royalty holder who owns a share of the production takes that share out of what the company may report, and the engine''s line reads "net entitlement: 70% working interest less the 15% royalty interest (PRMS 3.3.1.1)". A production tax is paid in money and takes out no volume (PRMS 3.3.1.2). The two forms print different figures, and net entitlement equals the working interest only under the tax.'),
  ('prms', 'intermediate', 'final', null, 34, 'A box states royalty.form as "cash". Which message comes back?', '["The royalty read as a production tax, since cash is paid", "royalty.form must be one of \"royalty-interest\", \"production-tax\"; got \"cash\"", "royalty.ratePct must be restated as a money amount for a royalty paid in cash; got nothing", "The royalty read as a royalty interest, the cautious reading"]'::jsonb, 1, 'The form is one of two stated words and the engine refuses anything else, printing the value. It maps no word onto either form, since the form moves every net-entitlement figure. The rate is a separate input and is stated on this call.'),
  ('prms', 'intermediate', 'final', null, 35, 'A cost table carries a key adr beside opex, capex and abandonment. What happens?', '["The adr cost is added to the abandonment in the final year", "costs.adr is refused as an unknown key, with opex, capex and abandonment listed", "costs.adr is dropped silently and the cash flow runs as stated", "The adr cost replaces the abandonment row"]'::jsonb, 1, 'The engine''s message reads "costs.adr is not an accepted key; the accepted keys of costs are opex, capex, abandonment". The engine reads no key it does not know and drops none silently, so nothing is added, dropped or replaced; the abandonment cost is stated under its own key.'),
  ('prms', 'intermediate', 'final', null, 36, 'Under the course''s vocabulary, what must the word entitlement always carry?', '["The date of the licence that grants the right to produce it", "The chance of commerciality of the project that holds it", "A discount rate used for the NPV", "A named basis: gross, working interest or net entitlement"]'::jsonb, 3, 'Entitlement is always the quantities on a named basis, and a figure quoted without its basis answers none of the three questions the bases answer. A licence date, a chance and a discount rate are each quoted with the figures they set, and none of them names whose share a quantity is.'),
  ('prms', 'intermediate', 'final', null, 37, 'The lease ends in 2040 with no renewal. Which volume of the low forecast sits past it?', '["1864516.000000 barrels", "601257.000000 barrels", "0.000000 barrels", "98956.000000 barrels"]'::jsonb, 3, 'The low case loses its 2041 row to the licence, 98956.000000 barrels. 1864516.000000 is the low case''s oil beyond the economic limit, a different cut. 601257.000000 is the high case''s oil beyond the licence. The low case stops paying in 2033 and still loses 2041 to the licence cut, which comes first.'),
  ('prms', 'intermediate', 'final', null, 38, 'With a renewal expected on EKN-1, what economic limit and oil beyond the licence does the high case return?', '["2040, with 601257.000000 barrels beyond the licence", "2041, with 601257.000000 barrels beyond the licence", "2041, with 0.000000 barrels beyond the licence", "2040, with 0.000000 barrels beyond the licence"]'::jsonb, 2, 'With a renewal expected no year is cut for the licence, so the high case runs to 2041, which pays, and its limit becomes 2041 with nothing beyond the licence. 2040 and 601257.000000 are the figures with no renewal, where the cut removes 2041 before the cash flow runs.'),
  ('prms', 'intermediate', 'final', null, 39, 'An EKN-1 box lacks reportingBasis and also carries an unknown top-level key basis. Which refusal comes first?', '["The missing input: reportingBasis must be one of the three bases; got nothing", "Neither: basis is read as the reporting basis and the call runs", "Both together, in one message naming the two fields", "The refusal on basis as a key the engine does not read"]'::jsonb, 3, 'Every function checks its accepted keys before it reads an input, so the engine returns "basis is not an accepted key; the accepted keys at the top level are effectiveYear, forecasts, prices, costs, royalty, tax, workingInterestPct, licence, reportingBasis, discountRatePct, mscfPerBoe". The missing basis is refused only once the key is fixed. The engine reads no near-match as a known key, and it refuses one field at a time.'),
  ('prms', 'intermediate', 'final', null, 40, 'EKN-1 states a commercial discovery declared 12 years ago. Which Nigerian note does the engine print?', '["A refusal, since a field development plan is overdue under PIA 2021 s.79(1)", "The note that the area is relinquished at the end of a 10-year retention", "The note that a field development plan was due within 2 years and the two-year period has passed", "A change of class to Contingent Resources until the plan is filed"]'::jsonb, 2, 'The engine''s note reads "commercial discovery declared (PIA 2021 s.78(8)(a)); a field development plan is due within 2 years of the declaration (s.79(1)); 12 years since the declaration: the two-year period has passed". Notes are printed beside the class and move no class; the engine refuses nothing for elapsed time. Retention and relinquishment belong to a significant discovery, and EKN-1 declares a commercial one.'),
  ('prms', 'intermediate', 'final', null, 41, 'The year of the fourth row of the EKN-1 best forecast is changed to 2031. Which message comes back?', '["The best case run with 2030 left out of the sums", "forecasts.best[3].year must be 2030 (one row a year from 2027, in order); got 2031", "forecasts.best must be sorted by year; got 2031", "prices must have 15 rows, one a year from 2027 to 2041; got 14"]'::jsonb, 1, 'The rows are checked before any arithmetic, and a gap is refused by the row''s path with the year it must hold, so no year can vanish from the sums unseen. The price table is complete here; the gap is in the forecast.'),
  ('prms', 'intermediate', 'final', null, 42, 'Under the course''s vocabulary, which inputs does a quoted Reserves figure carry with it?', '["Its basis, its forecast case, its economic limit and its licence", "Its unit and its category method alone", "Its chance of geologic discovery and its chance of development if found", "Its discount rate alone, since the NPV sets its value"]'::jsonb, 0, 'A figure that depends on an input is quoted with it, and a Reserves figure depends on the basis, the case, the economic limit and the licence. A unit and a method describe a category set, the two chances to a chance of commerciality, and the discount rate to an NPV.');
