-- ============================================================================
-- EC11 PROFESSIONAL DEEP SEED: Reserves & Resources under SPE-PRMS 2018, intermediate tier.
--
-- Six modules, 26 lessons, 132 questions (15 per module bank plus a 42
-- question final exam). The structure row is GENERATED from the tier's
-- manifest.json rather than hand typed, and the question rows from the
-- committed bank JSONs under tools/course-banks/prms/intermediate.
--
-- What this tier owns: MATURITY, COMMERCIALITY AND THE ECONOMIC LIMIT. The
-- project maturity sub-classes; the seven commerciality criteria and the firm
-- intention; incremental and cumulative categories; the economic limit of three
-- technical forecasts through the canonical cash flow, with 1P set to 0 when
-- the low case fails; entitlement on a stated basis; licence expiry.
--
-- AN ENGINE COURSE. There is no Suite app: the practicals run in the course's
-- own reserves calculator. The capstone grades six values of this tier, each identical
-- under every reading the engine states and never a Monte Carlo draw.
-- ============================================================================

values ('prms', 'intermediate', '{"modules":[{"key":"m01-project-maturity-sub-classes","title":"Project Maturity Sub-Classes","lesson_keys":["l01-on-production-approved-and-justified","l02-the-investment-decision","l03-pending-on-hold-unclarified-and-not-viable","l04-prospect-lead-and-play","l05-a-sub-class-the-facts-contradict"]},{"key":"m02-the-seven-commerciality-criteria","title":"The Seven Commerciality Criteria","lesson_keys":["l01-a-plan-money-and-a-time-frame","l02-economics-market-facilities-and-approvals","l03-the-five-year-benchmark","l04-the-firm-intention-to-proceed"]},{"key":"m03-incremental-and-cumulative-categories","title":"Incremental and Cumulative Categories","lesson_keys":["l01-increments-of-reserves","l02-building-the-cumulative-from-increments","l03-increments-from-three-forecasts","l04-a-zero-increment"]},{"key":"m04-the-economic-limit","title":"The Economic Limit","lesson_keys":["l01-three-technical-forecasts","l02-the-canonical-cash-flow-underneath","l03-trailing-years-cut-at-the-limit","l04-the-economic-test","l05-the-low-case-that-fails"]},{"key":"m05-entitlement-and-the-reporting-basis","title":"Entitlement and the Reporting Basis","lesson_keys":["l01-gross-working-interest-and-net-entitlement","l02-a-royalty-interest-and-a-production-tax","l03-barrels-of-oil-equivalent","l04-cash-flows-at-the-working-interest"]},{"key":"m06-licence-expiry-and-time","title":"Licence Expiry and Time","lesson_keys":["l01-production-beyond-the-licence","l02-when-renewal-is-expected","l03-capital-after-the-expiry","l04-the-capstone-brief"]}]}'::jsonb, 1)
